import React from 'react';

import Footer from '../Common/Footer';
import NavBar from '../Common/NavBar';
import TopAdspaces_1 from '../Adspaces/TopAdspaces_1';
import TopAdspaces_2 from '../Adspaces/TopAdspaces_2';
import TopAdspaces_3 from '../Adspaces/TopAdspaces_3';



// functional component 
export default function Dashboard() {
  return (
    <body classNameNameName="hold-transition sidebar-mini layout-navbar-fixed">
      <div classNameName="wrapper">
        <nav classNameName="main-header navbar navbar-expand navbar-white navbar-light">
          <ul classNameName="navbar-nav">
            <li classNameName="nav-item">
              <a classNameName="nav-link" data-widget="pushmenu" href="#" role="button"><i
                classNameName="fas fa-bars"></i></a>
            </li>
          </ul>
          <ul classNameName="navbar-nav ml-auto">
            <form action="" method="post">

              <input type="submit" value="Logout" classNameName="btn btn-sm  mt-3" />
            </form>
          </ul>
        </nav>
        <aside className="main-sidebar sidebar-dark-primary elevation-4">
          <a href="#" className="brand-link elevation-4">
            <img src="" alt="AdminLTE Logo"
              className="brand-image img-circle elevation-3" style="opacity: .8" />
            <span className="brand-text font-weight-light">EXPERTAFF</span>
          </a>
        </aside>
      </div>
    </body>
  )
}
